Here's a robust `buildUrl` function that handles arrays, nested `null`/`undefined` values, existing query strings, and hash fragments:

```javascript
/**
 * Builds a URL from a base path and a query parameters object.
 *
 * @param {string} base - The base URL or path (e.g. "https://api.example.com/users" or "/search").
 * @param {Object} [params={}] - Key/value pairs to append as query parameters.
 * @param {Object} [options={}]
 * @param {"repeat"|"brackets"|"comma"} [options.arrayFormat="repeat"] - How to serialize arrays.
 * @returns {string} The full URL with an encoded query string.
 */
function buildUrl(base, params = {}, { arrayFormat = "repeat" } = {}) {
  // Separate any hash fragment so query params are inserted before it
  const hashIndex = base.indexOf("#");
  const hash = hashIndex !== -1 ? base.slice(hashIndex) : "";
  let path = hashIndex !== -1 ? base.slice(0, hashIndex) : base;

  const encode = (value) => encodeURIComponent(value);

  const serializeValue = (value) => {
    if (value instanceof Date) return value.toISOString();
    if (typeof value === "object") return JSON.stringify(value);
    return String(value);
  };

  const pairs = [];

  for (const [key, value] of Object.entries(params)) {
    // Skip null and undefined values
    if (value === undefined || value === null) continue;

    if (Array.isArray(value)) {
      const items = value.filter((v) => v !== undefined && v !== null);
      if (items.length === 0) continue;

      switch (arrayFormat) {
        case "brackets": // tags[]=a&tags[]=b
          items.forEach((item) =>
            pairs.push(`${encode(key)}[]=${encode(serializeValue(item))}`)
          );
          break;
        case "comma": // tags=a,b
          pairs.push(
            `${encode(key)}=${items.map((i) => encode(serializeValue(i))).join(",")}`
          );
          break;
        case "repeat": // tags=a&tags=b
        default:
          items.forEach((item) =>
            pairs.push(`${encode(key)}=${encode(serializeValue(item))}`)
          );
      }
    } else {
      pairs.push(`${encode(key)}=${encode(serializeValue(value))}`);
    }
  }

  if (pairs.length === 0) return path + hash;

  // Append with "?" or "&" depending on whether a query string already exists
  let separator;
  if (!path.includes("?")) separator = "?";
  else if (path.endsWith("?") || path.endsWith("&")) separator = "";
  else separator = "&";

  return `${path}${separator}${pairs.join("&")}${hash}`;
}
```

### Usage examples

```javascript
// Basic usage
buildUrl("https://api.example.com/users", { page: 2, limit: 10 });
// → "https://api.example.com/users?page=2&limit=10"

// Special characters are encoded
buildUrl("/search", { q: "hello world & more", lang: "en" });
// → "/search?q=hello%20world%20%26%20more&lang=en"

// null/undefined values are skipped
buildUrl("/items", { sort: "name", filter: null, category: undefined });
// → "/items?sort=name"

// Arrays (default "repeat" format)
buildUrl("/posts", { tags: ["js", "web"] });
// → "/posts?tags=js&tags=web"

// Arrays with "brackets" format
buildUrl("/posts", { tags: ["js", "web"] }, { arrayFormat: "brackets" });
// → "/posts?tags%5B%5D=js&tags%5B%5D=web"  (decodes to tags[]=js&tags[]=web)

// Arrays with "comma" format
buildUrl("/posts", { tags: ["js", "web"] }, { arrayFormat: "comma" });
// → "/posts?tags=js,web"

// Base URL already has a query string
buildUrl("/search?q=test", { page: 3 });
// → "/search?q=test&page=3"

// Preserves hash fragments
buildUrl("/docs#section-2", { version: "1.0" });
// → "/docs?version=1.0#section-2"

// Dates and booleans
buildUrl("/events", { from: new Date("2024-01-01"), active: true });
// → "/events?from=2024-01-01T00%3A00%3A00.000Z&active=true"

// No params
buildUrl("/home");
// → "/home"
```

### Simpler alternative using the built-in `URL` API

If you're always working with absolute URLs (or can supply an origin), the native `URL` and `URLSearchParams` APIs handle encoding for you:

```javascript
function buildUrlNative(base, params = {}) {
  const url = new URL(base, "http://placeholder.local"); // origin used only for relative paths

  for (const [key, value] of Object.entries(params)) {
    if (value === undefined || value === null) continue;
    if (Array.isArray(value)) {
      value.forEach((v) => url.searchParams.append(key, v));
    } else {
      url.searchParams.set(key, value);
    }
  }

  // Return a relative path if the input was relative
  return /^https?:\/\//i.test(base)
    ? url.toString()
    : url.pathname + url.search + url.hash;
}

buildUrlNative("https://example.com/api", { q: "a b", ids: [1, 2] });
// → "https://example.com/api?q=a+b&ids=1&ids=2"
```

**Note:** `URLSearchParams` encodes spaces as `+` (form encoding), while the custom version uses `%20`. Both are generally accepted by servers, but `%20` is safer for non-form contexts.

### Key design decisions
- **`encodeURIComponent`** is used on both keys and values to safely handle special characters (`&`, `=`, `?`, spaces, Unicode).
- **`null`/`undefined` are skipped**, which is convenient for optional filters. Empty strings (`""`) and `0`/`false` are kept since they're often meaningful.
- **Hash fragments are preserved** and kept at the end, where they belong.
- **Existing query strings** in the base URL are respected.

Here's a robust function that builds a URL from a base path and a query parameters object:

```javascript
/**
 * Builds a URL from a base path and an object of query parameters.
 *
 * - Skips parameters whose value is `undefined` or `null`
 * - Supports array values (e.g. { tag: ['a', 'b'] } -> tag=a&tag=b)
 * - Serializes Date objects to ISO strings
 * - Serializes plain objects as JSON
 * - Preserves existing query strings and hash fragments in the base path
 * - Works with both absolute URLs and relative paths
 *
 * @param {string} basePath - The base URL or path (e.g. "https://api.example.com/users" or "/users")
 * @param {Object} [params={}] - Key/value pairs to append as query parameters
 * @returns {string} The full URL with an encoded query string
 */
function buildUrl(basePath, params = {}) {
  if (typeof basePath !== 'string') {
    throw new TypeError('basePath must be a string');
  }

  // Separate the hash fragment so query params are inserted before it
  const hashIndex = basePath.indexOf('#');
  const hash = hashIndex !== -1 ? basePath.slice(hashIndex) : '';
  const withoutHash = hashIndex !== -1 ? basePath.slice(0, hashIndex) : basePath;

  // Separate any existing query string
  const queryIndex = withoutHash.indexOf('?');
  const path = queryIndex !== -1 ? withoutHash.slice(0, queryIndex) : withoutHash;
  const existingQuery = queryIndex !== -1 ? withoutHash.slice(queryIndex + 1) : '';

  const searchParams = new URLSearchParams(existingQuery);

  const serialize = (value) => {
    if (value instanceof Date) return value.toISOString();
    if (typeof value === 'object') return JSON.stringify(value);
    return String(value);
  };

  for (const [key, value] of Object.entries(params || {})) {
    if (value === undefined || value === null) continue;

    if (Array.isArray(value)) {
      value
        .filter((v) => v !== undefined && v !== null)
        .forEach((v) => searchParams.append(key, serialize(v)));
    } else {
      searchParams.set(key, serialize(value));
    }
  }

  const queryString = searchParams.toString();
  return `${path}${queryString ? `?${queryString}` : ''}${hash}`;
}
```

