### Alternative: using the built-in `URL` API

If you're always working with absolute URLs (or can provide an origin), the native `URL` and `URLSearchParams` APIs are a concise option:

```javascript
function buildUrlNative(basePath, params = {}) {
  // A dummy origin allows relative paths to be parsed
  const isAbsolute = /^[a-z][a-z\d+\-.]*:\/\//i.test(basePath);
  const url = new URL(basePath, 'http://placeholder.local');

  for (const [key, value] of Object.entries(params)) {
    if (value == null) continue;
    if (Array.isArray(value)) {
      value.forEach((v) => v != null && url.searchParams.append(key, v));
    } else {
      url.searchParams.append(key, value);
    }
  }

  return isAbsolute ? url.toString() : url.pathname + url.search + url.hash;
}
```

**Note:** `URLSearchParams` encodes spaces as `+` rather than `%20`. Both are valid in query strings, but the first version gives you full control over encoding if a server expects a particular format.

Here's a robust URL builder that handles arrays, nested objects, null/undefined values, and existing query strings:

```javascript
/**
 * Builds a URL from a base path and a query parameters object.
 *
 * @param {string} base - The base URL or path (e.g., "https://api.example.com/users" or "/search")
 * @param {Object} [params={}] - Key/value pairs to add as query parameters
 * @param {Object} [options={}]
 * @param {"repeat"|"brackets"|"comma"} [options.arrayFormat="repeat"] - How arrays are serialized
 * @param {boolean} [options.skipEmptyString=false] - Omit params whose value is ""
 * @returns {string} The full URL with an encoded query string
 */
function buildUrl(base, params = {}, options = {}) {
  const { arrayFormat = "repeat", skipEmptyString = false } = options;

  // Separate any hash fragment so it stays at the end
  const [baseWithoutHash, hash] = base.split("#");

  const pairs = [];

  const encode = (value) => encodeURIComponent(value);

  const serializeValue = (value) => {
    if (value instanceof Date) return value.toISOString();
    return String(value);
  };

  const shouldSkip = (value) =>
    value === undefined ||
    value === null ||
    (skipEmptyString && value === "");

  const addPair = (key, value) => {
    if (shouldSkip(value)) return;

    if (Array.isArray(value)) {
      const filtered = value.filter((v) => !shouldSkip(v));
      if (filtered.length === 0) return;

      switch (arrayFormat) {
        case "brackets":
          filtered.forEach((v) =>
            pairs.push(`${encode(key + "[]")}=${encode(serializeValue(v))}`)
          );
          break;
        case "comma":
          pairs.push(
            `${encode(key)}=${filtered.map((v) => encode(serializeValue(v))).join(",")}`
          );
          break;
        case "repeat":
        default:
          filtered.forEach((v) =>
            pairs.push(`${encode(key)}=${encode(serializeValue(v))}`)
          );
      }
    } else if (typeof value === "object" && !(value instanceof Date)) {
      // Nested objects: { filter: { status: "active" } } -> filter[status]=active
      Object.entries(value).forEach(([subKey, subValue]) =>
        addPair(`${key}[${subKey}]`, subValue)
      );
    } else {
      pairs.push(`${encode(key)}=${encode(serializeValue(value))}`);
    }
  };

  Object.entries(params).forEach(([key, value]) => addPair(key, value));

  let url = baseWithoutHash;

  if (pairs.length > 0) {
    const queryString = pairs.join("&");
    if (!url.includes("?")) {
      url += "?" + queryString;
    } else if (url.endsWith("?") || url.endsWith("&")) {
      url += queryString;
    } else {
      url += "&" + queryString;
    }
  }

  if (hash !== undefined) {
    url += "#" + hash;
  }

  return url;
}
```

