**Note:** `new URL()` requires an absolute URL (or a second `base` argument like `new URL(path, window.location.origin)`), and `URLSearchParams` encodes spaces as `+` rather than `%20`. Both are valid, but the custom version gives you more control and works with relative paths.

Here's a robust function for building URLs with query parameters:

```javascript
/**
 * Builds a URL from a base path and a query parameters object.
 *
 * @param {string} base - The base URL or path (e.g., "https://api.example.com/users" or "/users")
 * @param {Object} [params={}] - Key/value pairs to append as query parameters
 * @returns {string} The full URL with encoded query string
 */
function buildUrl(base, params = {}) {
  // Separate any hash fragment so params are inserted before it
  const [pathAndQuery, hash] = base.split('#');

  const searchParams = new URLSearchParams();

  for (const [key, value] of Object.entries(params)) {
    // Skip null and undefined values
    if (value === null || value === undefined) continue;

    if (Array.isArray(value)) {
      // Arrays become repeated keys: ?tag=a&tag=b
      value
        .filter(v => v !== null && v !== undefined)
        .forEach(v => searchParams.append(key, String(v)));
    } else if (value instanceof Date) {
      searchParams.append(key, value.toISOString());
    } else if (typeof value === 'object') {
      // Nested objects are serialized as JSON
      searchParams.append(key, JSON.stringify(value));
    } else {
      searchParams.append(key, String(value));
    }
  }

  const queryString = searchParams.toString();

  let url = pathAndQuery;
  if (queryString) {
    // Use "&" if the base already contains a query string
    const separator = pathAndQuery.includes('?')
      ? (pathAndQuery.endsWith('?') || pathAndQuery.endsWith('&') ? '' : '&')
      : '?';
    url += separator + queryString;
  }

  return hash !== undefined ? `${url}#${hash}` : url;
}
```

