```javascript
/**
 * Builds a URL from a base path and a query parameters object.
 *
 * @param {string} base - The base URL or path (e.g., "https://api.example.com/users" or "/search")
 * @param {Object} [params={}] - Key/value pairs to append as query parameters
 * @returns {string} The complete URL
 *
