 * - Skips parameters whose value is null or undefined
 * - Arrays produce repeated keys: { tag: ['a', 'b'] } -> "tag=a&tag=b"
 * - Dates are serialized as ISO strings
 * - Objects are serialized as JSON
 * - Preserves existing query strings and hash fragments in the base
 */
function buildUrl(base, params = {}) {
  if (typeof base !== 'string') {
    throw new TypeError('Base must be a string');
  }

  // Split off any hash fragment so it stays at the end
  const [beforeHash, hash] = splitOnce(base, '#');
  // Split off any existing query string
  const [path, existingQuery] = splitOnce(beforeHash, '?');

  const searchParams = new URLSearchParams(existingQuery || '');

  for (const [key, value] of Object.entries(params || {})) {
    if (value === undefined || value === null) continue;

    if (Array.isArray(value)) {
      value
        .filter((v) => v !== undefined && v !== null)
        .forEach((v) => searchParams.append(key, serialize(v)));
    } else {
      searchParams.set(key, serialize(value));
    }
  }

  const queryString = searchParams.toString();

  return (
    path +
    (queryString ? `?${queryString}` : '') +
    (hash !== undefined ? `#${hash}` : '')
  );
}

function splitOnce(str, separator) {
  const index = str.indexOf(separator);
  return index === -1
    ? [str, undefined]
    : [str.slice(0, index), str.slice(index + 1)];
}

function serialize(value) {
  if (value instanceof Date) return value.toISOString();
  if (typeof value === 'object') return JSON.stringify(value);
  return String(value);
}
```

