```javascript
/**
 * Build a URL from a base path and a query parameters object.
 *
 * @param {string} basePath - Base URL or path (may already contain a query string and/or hash).
 * @param {Object} params - Key/value pairs to append as query parameters.
 * @param {Object} [options]
 * @param {boolean} [options.arrayFormat='repeat'] - How to encode arrays: 'repeat' (?a=1&a=2) or 'comma' (?a=1,2).
 * @param {boolean} [options.skipNullish=true] - Skip keys whose values are null or undefined.
 * @returns {string} The resulting URL.
 */
function buildUrl(basePath, params = {}, options = {}) {
  const { arrayFormat = 'repeat', skipNullish = true } = options;

  // Split off any hash fragment first so we don't encode it.
  const [withoutHash, hash = ''] = String(basePath).split('#', 2);
  const [path, existingQuery = ''] = withoutHash.split('?', 2);

  const searchParams = new URLSearchParams(existingQuery);

  const appendValue = (key, value) => {
    if (skipNullish && (value === null || value === undefined)) return;

    if (Array.isArray(value)) {
      const items = value.filter(
        (v) => !(skipNullish && (v === null || v === undefined))
      );
      if (arrayFormat === 'comma') {
        searchParams.append(key, items.map(String).join(','));
      } else {
        for (const item of items) searchParams.append(key, String(item));
      }
      return;
    }

    if (value instanceof Date) {
      searchParams.append(key, value.toISOString());
      return;
    }

    searchParams.append(key, String(value));
  };

  for (const [key, value] of Object.entries(params)) {
    appendValue(key, value);
  }

  // URLSearchParams encodes spaces as '+', which is valid but often unwanted in
  // path-ish URLs. Swap back to %20 for readability.
  const query = searchParams.toString().replace(/\+/g, '%20');

  return path + (query ? `?${query}` : '') + (hash ? `#${hash}` : '');
}

