And if you want to fully resolve relative paths against a base URL (e.g., `buildUrl('/api', ...)` → `https://example.com/api?...`), wrap the return value in `new URL(result, baseOrigin).toString()`.

# Building URLs with Query Parameters

Here's a robust implementation that handles the common edge cases you'll run into:

```javascript
/**
 * Builds a URL from a base path and a query parameters object.
 *
 * @param {string} base - The base URL or path (may already contain a query string).
 * @param {Object} [params] - Key/value pairs to append as query parameters.
 * @param {Object} [options]
 * @param {'repeat'|'comma'|'bracket'} [options.arrayFormat='repeat'] - How to serialize arrays.
 * @param {boolean} [options.skipNullish=true] - Skip null/undefined values.
 * @returns {string} The fully assembled URL.
 */
function buildUrl(base, params = {}, options = {}) {
  const { arrayFormat = 'repeat', skipNullish = true } = options;

  // Split the base into path and any pre-existing query string.
  const [path, existingQuery = ''] = String(base).split('?');
  const search = new URLSearchParams(existingQuery);

  const append = (key, value) => {
    if (skipNullish && (value === null || value === undefined)) return;

    if (Array.isArray(value)) {
      if (value.length === 0) return;

      switch (arrayFormat) {
        case 'comma':
          search.append(key, value.join(','));
          break;
        case 'bracket':
          value.forEach((v) => search.append(`${key}[]`, v));
          break;
        case 'repeat':
        default:
          value.forEach((v) => search.append(key, v));
      }
    } else if (value instanceof Date) {
      search.append(key, value.toISOString());
    } else if (typeof value === 'object') {
      search.append(key, JSON.stringify(value));
    } else {
      search.append(key, String(value));
    }
  };

  for (const [key, value] of Object.entries(params)) {
    append(key, value);
  }

  const qs = search.toString();
  return qs ? `${path}?${qs}` : path;
}
```

## Usage

```javascript
buildUrl('/api/users');
// '/api/users'

buildUrl('/api/users', { page: 2, limit: 20, active: true });
// '/api/users?page=2&limit=20&active=true'

buildUrl('/api/search', { q: 'hello world', tags: ['js', 'web'] });
// '/api/search?q=hello+world&tags=js&tags=web'

buildUrl('/api/search', { tags: ['js', 'web'] }, { arrayFormat: 'comma' });
// '/api/search?tags=js%2Cweb'

buildUrl('/api/items?sort=asc', { page: 3 });
// '/api/items?sort=asc&page=3'

buildUrl('/api/users', { name: 'Ann', age: null, nickname: undefined });
// '/api/users?name=Ann'
```

## Why this approach

- **`URLSearchParams`** handles all the encoding for you — spaces become `+`, `&`/`=`/unicode get escaped correctly, and you don't have to worry about manual `encodeURIComponent` calls.
- **Merging with an existing query string** in `base` means you can pass a URL that already has params without clobbering them.
- **Array handling is configurable** because different backends expect different conventions (`?tag=a&tag=b` vs `?tag=a,b` vs `?tag[]=a&tag[]=b`).
- **Nullish values are skipped by default** so you can pass sparse objects (e.g. from a form) without producing `?foo=null`.

If you need this to also work with absolute URLs and want to preserve hash fragments, swap the manual split for `new URL(base, 'http://x')` and read/write `.search` and `.hash` on it.

# Building URLs with Query Parameters

Here's a robust implementation that handles arrays, null/undefined values, existing query strings, and proper encoding:

```javascript
/**
 * Builds a URL from a base path and a query parameters object.
 *
 * @param {string} basePath - The base URL or path (may already contain a query string).
 * @param {Object} [params] - Key/value pairs to append as query parameters.
 *   - Arrays are expanded into repeated keys: { a: [1, 2] } -> ?a=1&a=2
 *   - null and undefined values are skipped.
 *   - Nested objects are JSON-stringified.
 * @returns {string} The fully constructed URL.
 */
function buildUrl(basePath, params = {}) {
  if (typeof basePath !== 'string' || basePath.length === 0) {
    throw new TypeError('basePath must be a non-empty string');
  }

  // Split off any existing query string and hash fragment.
  const hashIndex = basePath.indexOf('#');
  const hash = hashIndex >= 0 ? basePath.slice(hashIndex) : '';
  const withoutHash = hashIndex >= 0 ? basePath.slice(0, hashIndex) : basePath;

  const queryIndex = withoutHash.indexOf('?');
  const path = queryIndex >= 0 ? withoutHash.slice(0, queryIndex) : withoutHash;
  const existingQuery = queryIndex >= 0 ? withoutHash.slice(queryIndex + 1) : '';

  // Start with any existing params so new ones override them.
  const search = new URLSearchParams(existingQuery);

  for (const [key, value] of Object.entries(params)) {
    if (value === null || value === undefined) continue;

    if (Array.isArray(value)) {
      for (const item of value) {
        if (item === null || item === undefined) continue;
        search.append(key, serializeValue(item));
      }
    } else {
      search.set(key, serializeValue(value));
    }
  }

  const queryString = search.toString();
  return path + (queryString ? `?${queryString}` : '') + hash;
}

function serializeValue(value) {
  if (typeof value === 'object') return JSON.stringify(value);
  return String(value);
}
```

