 * @param {Intl.CollatorOptions} [options] - Optional collator options
 * @returns {Array<{ name?: string, active?: boolean }>} A new array of active users
 */
function getActiveUsers(users, locale, options = {}) {
  if (!Array.isArray(users)) {
    throw new TypeError('getActiveUsers expects an array of users');
