## `buildUrl(basePath, params, options)`

```js
/**
 * Build a URL from a base path and a query-parameters object.
 *
 * @param {string} basePath
 *   Base path or absolute URL. May already contain a query string and/or a
 *   hash fragment — both are preserved.
 * @param {Record<string, unknown>} [params]
 *   Query parameters. `null`/`undefined` values are skipped by default.
 *   Arrays are expanded (one pair per item); plain objects are JSON-encoded.
 * @param {object} [options]
 * @param {boolean} [options.encode=true]       Percent-encode keys and values.
 * @param {boolean} [options.skipNullish=true]  Drop `null`/`undefined` values.
 * @param {'repeat'|'comma'|'brackets'} [options.arrayFormat='repeat']
 *   How array values are serialized.
 * @returns {string} The assembled URL.
 */
function buildUrl(basePath, params = {}, options = {}) {
  if (typeof basePath !== 'string') {
    throw new TypeError('buildUrl: basePath must be a string');
  }

  const { encode = true, skipNullish = true, arrayFormat = 'repeat' } = options;

  // 1. Split the base into path / query / hash
  let rest = basePath;
  let hash = '';

  const hashAt = rest.indexOf('#');
  if (hashAt !== -1) {
    hash = rest.slice(hashAt);
    rest = rest.slice(0, hashAt);
  }

  let path = rest;
  let query = '';
  const queryAt = rest.indexOf('?');
  if (queryAt !== -1) {
    path = rest.slice(0, queryAt);
    query = rest.slice(queryAt + 1);
  }

  // 2. Serialize the parameters
  const enc = encode ? encodeURIComponent : (s) => s;
  const pairs = [];
  const push = (key, value) => pairs.push(`${enc(key)}=${enc(value)}`);

  for (const [key, value] of Object.entries(params ?? {})) {
    if (value === null || value === undefined) {
      if (skipNullish) continue;
      push(key, '');
      continue;
    }

    if (Array.isArray(value)) {
      const items = value.filter(
        (v) => !(skipNullish && (v === null || v === undefined))
      );
      if (arrayFormat === 'comma') {
        push(key, items.map(stringifyValue).join(','));
      } else if (arrayFormat === 'brackets') {
        for (const item of items) push(`${key}[]`, stringifyValue(item));
      } else {
        for (const item of items) push(key, stringifyValue(item));
      }
      continue;
    }

    push(key, stringifyValue(value));
  }

  // 3. Merge with any query string already present on the base
  const merged = [query, pairs.join('&')].filter(Boolean).join('&');

  return `${path}${merged ? `?${merged}` : ''}${hash}`;
}

function stringifyValue(value) {
  if (value instanceof Date) return value.toISOString();
  if (typeof value === 'object') return JSON.stringify(value);
  return String(value);
}
```

## Examples

```js
buildUrl('/api/users', { page: 1, limit: 20 });
// '/api/users?page=1&limit=20'

buildUrl('/api/users', { q: 'a b&c', tags: ['x', 'y'] });
// '/api/users?q=a%20b%26c&tags=x&tags=y'

buildUrl('/api/users?sort=name#top', { page: 2 });
// '/api/users?sort=name&page=2#top'   ← existing query & hash preserved

buildUrl('/api/users', { filter: { age: 30 }, when: new Date('2024-01-01') });
// '/api/users?filter=%7B%22age%3A30%7D&when=2024-01-01T00%3A00%3A00.000Z'

buildUrl('/api/users', { a: null, b: undefined, c: 0, d: false });
// '/api/users?c=0&d=false'            ← nullish skipped, falsy kept

buildUrl('/api/users', { tags: ['a', 'b'] }, { arrayFormat: 'comma' });
// '/api/users?tags=a,b'
```

## Notes

- **Falsy vs. nullish:** `0`, `false`, and `''` are kept; only `null`/`undefined` are dropped (set `skipNullish: false` to emit them as empty values).
- **`encode: false`** leaves keys/values raw — only safe when you know the input contains no `&`, `=`, `#`, or spaces.
- **Absolute URLs:** if you need origin normalization, `new URL(path, origin)` plus `URLSearchParams` is a good alternative:

  ```js
