```javascript
/**
 * Builds a URL from a base path and a query parameters object.
 *
 * @param {string} basePath - The base path/URL (e.g. "https://api.example.com/search")
 * @param {Object} [params] - Query parameters. Use arrays for repeated keys,
 *                            and null/undefined values are omitted.
 * @returns {string} The full URL with the query string appended.
 */
function buildUrl(basePath, params = {}) {
  const url = new URL(basePath, 'https://example.com'); // base for relative paths
  const search = new URLSearchParams();

  for (const [key, value] of Object.entries(params)) {
    if (value === null || value === undefined) continue;

    if (Array.isArray(value)) {
      for (const item of value) {
        if (item !== null && item !== undefined) {
          search.append(key, String(item));
        }
      }
    } else {
      search.append(key, String(value));
    }
  }

  const query = search.toString();
  if (query) {
    url.search = query;
  }

  // Return an absolute URL only if the input was absolute
  return /^https?:\/\//i.test(basePath) ? url.toString() : `${url.pathname}${url.search}`;
}

// Example:
