## `buildUrl(basePath, params, options)`

```js
/**
 * Build a URL from a base path and a query-parameters object.
 *
 * @param {string} basePath  e.g. "/api/search" or "https://example.com/api"
 * @param {object} params    e.g. { q: "cats", tags: ["a", "b"], page: 2 }
 * @param {object} [options]
 * @param {boolean} [options.encode=true]      Percent-encode keys and values
 * @param {'repeat'|'comma'|'brackets'} [options.arrayFormat='repeat']
 *        How array values are serialized:
 *          repeat   -> ?tags=a&tags=b
 *          comma    -> ?tags=a,b
 *          brackets -> ?tags[]=a&tags[]=b
 * @param {boolean} [options.skipNullish=true] Skip null/undefined values
 * @returns {string}
 */
function buildUrl(basePath, params = {}, options = {}) {
  const {
    encode = true,
    arrayFormat = 'repeat',
    skipNullish = true,
  } = options;

  if (typeof basePath !== 'string') {
    throw new TypeError('buildUrl: basePath must be a string');
  }
  if (params === null || typeof params !== 'object') {
    throw new TypeError('buildUrl: params must be an object');
  }

  // 1. Peel off the hash fragment (#section)
  let rest = basePath;
  let hash = '';
  const hashIdx = rest.indexOf('#');
  if (hashIdx !== -1) {
    hash = rest.slice(hashIdx);
    rest = rest.slice(0, hashIdx);
  }

  // 2. Peel off any query string already present on the base path
  let path = rest;
  let existingQuery = '';
  const queryIdx = rest.indexOf('?');
  if (queryIdx !== -1) {
    existingQuery = rest.slice(queryIdx + 1);
    path = rest.slice(0, queryIdx);
  }

  // 3. Collect [key, value] pairs
  const pairs = [];

  // Keep pre-existing query params (they come first)
  if (existingQuery) {
    for (const [k, v] of new URLSearchParams(existingQuery)) pairs.push([k, v]);
  }

  for (const [key, value] of Object.entries(params)) {
    if (value === undefined || value === null) {
      if (skipNullish) continue;
      pairs.push([key, '']);
      continue;
    }

    if (Array.isArray(value)) {
      if (value.length === 0) continue;
      switch (arrayFormat) {
        case 'comma':
          pairs.push([key, value.join(',')]);
          break;
        case 'brackets':
          for (const v of value) pairs.push([`${key}[]`, v]);
          break;
        case 'repeat':
        default:
          for (const v of value) pairs.push([key, v]);
      }
      continue;
    }

    if (value instanceof Date) {
      pairs.push([key, value.toISOString()]);
    } else if (typeof value === 'object') {
      pairs.push([key, JSON.stringify(value)]);
    } else {
      pairs.push([key, String(value)]);
    }
  }

  // 4. Serialize
  const queryString = pairs
    .map(([k, v]) => {
      const key = encode ? encodeURIComponent(k) : k;
      const val = encode ? encodeURIComponent(v) : v;
      return `${key}=${val}`;
    })
    .join('&');

  return `${path}${queryString ? `?${queryString}` : ''}${hash}`;
}
```

