 *   May already contain a query string and/or a hash fragment.
 * @param {Object} [params={}]
 *   Query parameters. Supported value types:
 *     - string / number / boolean  -> converted with String()
 *     - Date                      -> ISO 8601 string
 *     - Array                     -> repeated key (e.g. ?tag=a&tag=b)
 *     - plain Object              -> JSON.stringify'd
 *     - null / undefined          -> key is omitted
 * @param {Object} [options={}]
 * @param {boolean} [options.spaceAsPlus=true]  Encode spaces as "+" (true) or "%20" (false).
 * @returns {string}
 */
function buildUrl(basePath, params = {}, options = {}) {
  if (typeof basePath !== 'string' || basePath.length === 0) {
    throw new TypeError('buildUrl: basePath must be a non-empty string');
  }

  const { spaceAsPlus = true } = options;

  // 1. Split off the hash fragment so params land *before* it.
  const hashIdx = basePath.indexOf('#');
  const hash = hashIdx === -1 ? '' : basePath.slice(hashIdx);
  const withoutHash = hashIdx === -1 ? basePath : basePath.slice(0, hashIdx);

  // 2. Split off any existing query string.
  const queryIdx = withoutHash.indexOf('?');
  const existingQuery = queryIdx === -1 ? '' : withoutHash.slice(queryIdx + 1);
  const path = queryIdx === -1 ? withoutHash : withoutHash.slice(0, queryIdx);

  // 3. Merge params into the search params (params override the base's values).
  const search = new URLSearchParams(existingQuery);

  for (const [key, value] of Object.entries(params)) {
    if (value === undefined || value === null) continue;

    if (Array.isArray(value)) {
      search.delete(key);
      for (const item of value) {
        if (item === undefined || item === null) continue;
        search.append(key, serialize(item));
      }
    } else {
      search.set(key, serialize(value));
    }
  }

