## Implementation

```js
/**
 * Builds a URL from a base path and a query parameters object.
 *
 * @param {string} basePath - e.g. "/api/users" or "https://example.com/api/users"
 * @param {Object} params   - e.g. { page: 1, tags: ["a", "b"] }
 * @returns {string}        - the resulting URL
 */
function buildUrl(basePath, params = {}) {
  // Use a dummy base so relative paths work with the URL API
  const isAbsolute = /^[a-zA-Z][a-zA-Z\d+\-.]*:\/\//.test(basePath);
  const url = new URL(basePath, "http://localhost");

  for (const [key, value] of Object.entries(params)) {
    if (value === null || value === undefined) continue; // skip empty values

    if (Array.isArray(value)) {
      // Arrays become repeated keys: ?tag=a&tag=b
      for (const item of value) {
        if (item !== null && item !== undefined) url.searchParams.append(key, item);
      }
    } else {
      url.searchParams.append(key, value);
    }
  }

  return isAbsolute
    ? url.href
    : url.pathname + url.search + url.hash;
}
```

