## `buildUrl(basePath, params)`

```js
/**
 * Builds a URL from a base path and an object of query parameters.
 *
 * - Preserves any existing query string and hash fragment in the base path
 * - Arrays produce repeated keys (e.g. ?tag=a&tag=b)
 * - null / undefined values are omitted
 * - Values are URL-encoded automatically
 *
 * @param {string} basePath - e.g. "https://example.com/api/users" or "/api/users"
 * @param {Object} [params={}] - Query parameters
 * @returns {string} The built URL
 */
function buildUrl(basePath, params = {}) {
  if (typeof basePath !== 'string') {
    throw new TypeError('basePath must be a string');
  }

  // Split off hash fragment (#section)
  const hashIndex = basePath.indexOf('#');
  const hash = hashIndex !== -1 ? basePath.slice(hashIndex) : '';
  let path = hashIndex !== -1 ? basePath.slice(0, hashIndex) : basePath;

  // Split off existing query string (?a=1)
  const queryIndex = path.indexOf('?');
  const existingQuery = queryIndex !== -1 ? path.slice(queryIndex + 1) : '';
  path = queryIndex !== -1 ? path.slice(0, queryIndex) : path;

  const search = new URLSearchParams(existingQuery);

  for (const [key, value] of Object.entries(params)) {
    if (value === undefined || value === null) continue;

    if (Array.isArray(value)) {
      for (const item of value) {
        if (item !== undefined && item !== null) search.append(key, String(item));
      }
    } else {
      search.append(key, String(value));
    }
  }

  const queryString = search.toString();
  return `${path}${queryString ? `?${queryString}` : ''}${hash}`;
}
```

