## The function

```js
/**
 * Build a URL from a base path and a query-params object.
 *
 * @param {string} basePath  e.g. "/api/users" or "https://example.com/api/users"
 * @param {object} [params]  e.g. { page: 2, tags: ['a', 'b'] }
 * @returns {string}
 */
function buildUrl(basePath, params = {}) {
  if (typeof basePath !== 'string' || basePath.trim() === '') {
    throw new TypeError('buildUrl: basePath must be a non-empty string');
  }
  if (params === null || typeof params !== 'object') {
    throw new TypeError('buildUrl: params must be an object');
  }

  // 1. Peel off the hash fragment (#section)
  const hashIdx = basePath.indexOf('#');
  const hash = hashIdx === -1 ? '' : basePath.slice(hashIdx);
  const noHash = hashIdx === -1 ? basePath : basePath.slice(0, hashIdx);

  // 2. Peel off any query string already present
  const qIdx = noHash.indexOf('?');
  const path = qIdx === -1 ? noHash : noHash.slice(0, qIdx);
  const existingQuery = qIdx === -1 ? '' : noHash.slice(qIdx + 1);

  // 3. Merge existing query with the new params
  const search = new URLSearchParams(existingQuery);
  appendParams(search, params);

  const query = search.toString();
  return query ? `${path}?${query}${hash}` : `${path}${hash}`;
}

function appendParams(search, params, prefix = '') {
  for (const [key, value] of Object.entries(params)) {
    if (value === undefined || value === null) continue; // skip empty values
    const name = prefix ? `${prefix}[${key}]` : key;

    if (Array.isArray(value)) {
      for (const item of value) {
        if (item === undefined || item === null) continue;
        search.append(name, toValue(item));
      }
    } else if (value instanceof Date) {
      search.append(name, value.toISOString());
    } else if (typeof value === 'object') {
      appendParams(search, value, name); // nested -> filter[name]=x
    } else {
      search.append(name, toValue(value));
    }
  }
}

function toValue(value) {
  if (typeof value === 'boolean') return value ? 'true' : 'false';
  return String(value);
}
```

