### Examples

```js
buildUrl('/api/users', { page: 1, limit: 20, q: 'hello world' });
// "/api/users?page=1&limit=20&q=hello+world"

buildUrl('/search', { tag: ['js', 'node'], empty: null, missing: undefined });
// "/search?tag=js&tag=node"

buildUrl('/api/users', {});
// "/api/users"
```

### Notes

- **Encoding** is handled automatically by `URLSearchParams` — spaces become `+`, and special characters are percent-encoded (`&`, `=`, `#`, etc.).
- **`null` / `undefined`** values are skipped rather than serialized as the strings `"null"` / `"undefined"`.
- If you need the full absolute URL instead of just the path, return `url.toString()` (and then `origin` matters).

### Alternative without the `URL` API

If you want to avoid the dummy origin entirely:

```js
function buildUrl(basePath, params = {}) {
  const search = new URLSearchParams();
  for (const [key, value] of Object.entries(params)) {
    if (value === undefined || value === null) continue;
    if (Array.isArray(value)) {
      value.forEach(v => v != null && search.append(key, v));
    } else {
      search.set(key, value);
    }
  }
  const qs = search.toString();
  return qs ? `${basePath}?${qs}` : basePath;
}
```

This one is simpler and keeps the base path exactly as given (no origin resolution), which is handy when you're building relative URLs for `fetch`.

```javascript
/**
 * Builds a URL from a base path and an object of query parameters.
 *
 * @param {string} basePath - The base path/URL (e.g. "/api/users" or "https://example.com/api")
 * @param {Object} params - Query parameters (values may be primitives or arrays)
 * @returns {string} The constructed URL
 */
function buildUrl(basePath, params = {}) {
  const url = new URL(basePath, "https://example.com"); // base for relative paths
  const searchParams = new URLSearchParams();

  for (const [key, value] of Object.entries(params)) {
    if (value === undefined || value === null) continue; // skip empty values

    if (Array.isArray(value)) {
      for (const item of value) {
        if (item !== undefined && item !== null) {
          searchParams.append(key, item);
        }
      }
    } else {
      searchParams.append(key, value);
    }
  }

  const query = searchParams.toString();
  url.search = query ? `?${query}` : "";

  // Preserve relative paths if the original base was relative
  return url.origin === "https://example.com" && !/^https?:\/\//i.test(basePath)
    ? `${url.pathname}${url.search}`
    : url.toString();
}

// Example
console.log(buildUrl("/api/users", { page: 1, search: "john doe", tags: ["a", "b"] }));
// /api/users?page=1&search=john+doe&tags=a&tags=b

console.log(buildUrl("https://example.com/api", { id: 42 }));
// https://example.com/api?id=42
```

**Notes:**
- Uses `URLSearchParams` so values are properly URL-encoded (spaces become `+`, special characters are escaped).
- `undefined` and `null` values are skipped.
- Array values produce repeated keys (`?tags=a&tags=b`), a common convention for multi-value filters.
- Relative base paths stay relative; absolute URLs are preserved.

If you don't need array support or relative-path handling, a simpler version works too:

```javascript
function buildUrl(basePath, params = {}) {
  const query = new URLSearchParams(
    Object.entries(params).filter(([, v]) => v !== undefined && v !== null)
  ).toString();

  return query ? `${basePath}?${query}` : basePath;
}
```

## Implementation

```js
/**
 * Build a URL from a base path and a query-parameter object.
 *
 * @param {string} basePath              e.g. "/search" or "/search?sort=asc#top"
 * @param {Record<string, unknown>} params
 * @param {object}  [options]
 * @param {boolean} [options.skipNull=true]    omit null/undefined values
 * @param {boolean} [options.nested=false]     serialize objects as `a[b]=c`
 * @param {string}  [options.arrayFormat='repeat']  'repeat' | 'comma' | 'indices'
 * @returns {string}
 */
function buildUrl(basePath = '', params = {}, options = {}) {
  const { skipNull = true, nested = false, arrayFormat = 'repeat' } = options;

  // 1. Peel off the hash fragment so it stays at the end of the URL.
  const hashIdx = basePath.indexOf('#');
  const hash = hashIdx >= 0 ? basePath.slice(hashIdx) : '';
  let path = hashIdx >= 0 ? basePath.slice(0, hashIdx) : basePath;

  // 2. Peel off any query string already present in the base path.
  const queryIdx = path.indexOf('?');
  const existingQuery = queryIdx >= 0 ? path.slice(queryIdx + 1) : '';
  path = queryIdx >= 0 ? path.slice(0, queryIdx) : path;

  const pairs = [];
  // Encode keys but keep [] literal (common for nested/array syntax).
  const encKey = (k) => encodeURIComponent(k).replace(/%5B/g, '[').replace(/%5D/g, ']');
  const encVal = (v) => encodeURIComponent(String(v));

  function append(key, value) {
    if (value === null || value === undefined) {
      if (!skipNull) pairs.push(`${encKey(key)}=`);
      return;
    }
    if (value instanceof Date) {
      pairs.push(`${encKey(key)}=${encVal(value.toISOString())}`);
      return;
    }
    if (Array.isArray(value)) {
      if (value.length === 0) return;
      if (arrayFormat === 'comma') {
        pairs.push(`${encKey(key)}=${encVal(value.join(','))}`);
      } else if (arrayFormat === 'indices') {
        value.forEach((v, i) => append(`${key}[${i}]`, v));
      } else {
        value.forEach((v) => append(key, v)); // 'repeat'
      }
      return;
    }
    if (typeof value === 'object') {
      if (!nested) {
        pairs.push(`${encKey(key)}=${encVal(JSON.stringify(value))}`);
        return;
      }
      for (const [k, v] of Object.entries(value)) append(`${key}[${k}]`, v);
      return;
    }
    pairs.push(`${encKey(key)}=${encVal(value)}`);
  }

  for (const [key, value] of Object.entries(params)) append(key, value);

  const query = [existingQuery, pairs.join('&')].filter(Boolean).join('&');
  return `${path}${query ? `?${query}` : ''}${hash}`;
}
```

## Examples

```js
buildUrl('/search', { q: 'hello world', page: 2 });
// "/search?q=hello%20world&page=2"

buildUrl('/search', { tag: ['a', 'b'], draft: null });
// "/search?tag=a&tag=b"                      (null skipped)

buildUrl('/search', { tag: ['a', 'b'] }, { arrayFormat: 'comma' });
// "/search?tag=a%2Cb"

buildUrl('/search', { filters: { color: 'red', size: 'L' } }, { nested: true });
// "/search?filters[color]=red&filters[size]=L"

buildUrl('/search?sort=asc#results', { q: 'x' });
// "/search?sort=asc&q=x#results"             (existing query + hash preserved)

buildUrl('/search', { when: new Date('2024-01-01T00:00:00Z') });
// "/search?when=2024-01-01T00%3A00%3A00.000Z"
```

## Notes

- **Encoding**: keys and values are `encodeURIComponent`-encoded, so spaces become `%20` and reserved characters (`&`, `=`, `#`, `?`) are safely escaped.
- **Empty arrays** are omitted entirely; `null`/`undefined` are skipped unless you pass `{ skipNull: false }`, which emits `key=`.
- **Simpler alternative** when you don't need the extra formatting options — `URLSearchParams` handles encoding for you:

```js
function buildUrlSimple(base, params = {}) {
  const search = new URLSearchParams();
  for (const [k, v] of Object.entries(params)) {
    if (v === null || v === undefined) continue;
    if (Array.isArray(v)) v.forEach(x => search.append(k, x));
    else search.append(k, v);
  }
  const qs = search.toString();
  return `${base}${qs ? `?${qs}` : ''}`;
}
```

One difference: `URLSearchParams` encodes spaces as `+` rather than `%20` — fine for query strings, but keep the manual version if you need strict RFC 3986 percent-encoding.
